(()=>{class e{static selectors={elSetupForm:"#learn-press-setup-form",elPreviewPrice:"#preview-price"};init(){this.elSetupForm=document.querySelector(e.selectors.elSetupForm),this.elSetupForm&&this.events()}events(){document.addEventListener("change",e=>{e.target.closest("input, select")&&this.saveSettings()})}saveSettings(){const t=new FormData(this.elSetupForm);fetch(window.location.href,{method:"POST",body:t}).then(e=>e.text()).then(t=>{const s=document.querySelector(e.selectors.elPreviewPrice);s&&(s.innerHTML=t)})}}document.addEventListener("DOMContentLoaded",()=>{(new e).init()})})();